	subroutine decayWll(amp, i1, i2, i3)
	use basic_funcs_FC6
	implicit none
	double complex amp, Fx1
	integer i1, i2, i3

#include "vars.h"

	Fx1 = Hel(i2)*SxS(DottedSpinor(i3,1,7),VxS(e(i1),Spinor(i2,-1,7)))
	amp = EL*Fx1/(SW*Sqrt(2.D0))

#ifdef DEBUG
	DEB 'decayWll: vec =', vec(1,1,1,i2), Hel(i2)
	DEB 'decayWll: amp =', amp, Fx1
c	stop
#endif

	end
